    // Basic sanity check: must be a non-empty string
    if (!file || typeof file !== 'string') {
      return res.status(400).send('Missing or invalid "file" parameter.');
    }

    // Restrict to safe filenames (alphanumeric, underscore, dash, dot)
    const SAFE_FILENAME_RE = /^[a-zA-Z0-9_.-]+$/;
    if (!SAFE_FILENAME_RE.test(file)) {
      return res.status(400).send('Invalid file name.');
    }

    // Resolve the full path safely and ensure it stays within uploads/
    const uploadPath = path.resolve(__dirname, 'uploads', file);
    if (!uploadPath.startsWith(path.resolve(__dirname, 'uploads'))) {
      return res.status(400).send('Attempted directory traversal detected.');
