const fs = require('fs');
const path = require('path');

const cache = {};

// Allowed characters for a locale: letters, digits, underscore and hyphen.
// This prevents directory traversal attacks such as ../../etc/passwd.json.
const VALID_LOCALE_RE = /^[a-zA-Z0-9_-]+$/;

// Maximum length for a locale string to avoid overly large inputs.
const MAX_LOCALE_LENGTH = 20;

/**
 * Loads the JSON file containing UI strings for the given locale.
 * The result is cached in memory for subsequent requests.
 *
 * @param {string} locale - The requested locale (already validated).
 * @param {(err: Error|null, data?: string) => void} cb
 */
function loadStrings(locale, cb) {
  // Return cached content if available.
  if (cache[locale]) return process.nextTick(() => cb(null, cache[locale]));

  // Build the absolute path to the locale file safely.
  const localeFile = path.join(
    __dirname,
    '..',
    'public',
    'locales',
    `${locale}.json`
  );

  fs.readFile(localeFile, 'utf8', (err, data) => {
    if (!err && typeof data === 'string') {
      cache[locale] = data; // Cache the successful read.
    }
    cb(err, data);
  });
}

