 * Express-like request handler that serves UI strings based on
 * the `x-locale` header. Untrusted input is validated before use.
 *
 * @param {{ headers: Record<string,string> }} req
 * @param {{ send: (body:string) => void }} res
 */
module.exports = function handler(req, res) {
  try {
    let locale = req.headers['x-locale'] || 'en';

    // Basic validation of the locale header.
    if (
      typeof locale !== 'string' ||
      !VALID_LOCALE_RE.test(locale) ||
      locale.length > MAX_LOCALE_LENGTH
    ) {
      locale = 'en'; // Fallback to default locale on invalid input.
    }

