      if (err) {
        console.warn(`Failed to load strings for locale "${locale}":`, err);
        res.send('{}'); // Return empty JSON object on error.
      } else {
        res.send(data || '{}');
      }
    });
  } catch (e) {
    // Catch any unexpected synchronous errors and respond safely.
    console.error('Unexpected error in handler:', e);
    res.send('{}');
  }
};
