  const backupName = req.body && typeof req.body.backup === 'string'
    ? req.body.backup
    : null;

  if (!backupName) {
    return res.status(400).send('Missing or invalid backup name');
  }

  // 2️⃣ Enforce a strict naming policy (e.g., only alphanumerics, dashes, underscores, and .json extension).
  const allowedPattern = /^[a-zA-Z0-9_-]+\.json$/;
  if (!allowedPattern.test(backupName)) {
    return res.status(400).send('Invalid backup name');
  }

  // 3️⃣ Resolve the absolute path safely using `path.join`.
  const targetPath = path.join(BACKUPS_DIR, backupName);

  try {
    // 4️⃣ Resolve any symlinks and ensure the final path is still inside BACKUPS_DIR.
    const realTarget = fs.realpathSync(targetPath);
    if (!realTarget.startsWith(BACKUPS_DIR + path.sep)) {
      return res.status(403).send('Access denied');
    }

    // 5️⃣ Read and send the file contents.
    const data = fs.readFileSync(realTarget, 'utf8');
    res.send(data);
